    private void addStockConfirmActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_addStockConfirmActionPerformed
try {
    // 1. Get the current date automatically
    java.time.LocalDate today = java.time.LocalDate.now();
    String dateStr = today.toString(); 

    // 2. CREATE THE VARIABLES (Do this first!)
    int currentQty = Integer.parseInt(admin.tableInventory1.getValueAt(selectedRow, 2).toString());
    int addedQty = Integer.parseInt(txtAddStock.getText()); // This creates addedQty
    int totalQty = currentQty + addedQty;
    
    // Get the name of the item
    String itemName = admin.tableInventory1.getValueAt(selectedRow, 1).toString(); // This creates itemName

    // 3. Update the Main Table Columns
    admin.tableInventory1.setValueAt(totalQty, selectedRow, 2);
    admin.tableInventory1.setValueAt(dateStr, selectedRow, 6);
    admin.tableInventory1.setValueAt(addedQty, selectedRow, 7);

    // 4. Trigger the Status Update
    admin.updateStatus(selectedRow);

    // 5. Save and Log (Now these will work because the variables above exist!)
    admin.saveInventoryFromTable();
    admin.logHistory(itemName + " was restocked and was added " + addedQty + " units.");
    
    this.dispose();

} catch (NumberFormatException e) {
    javax.swing.JOptionPane.showMessageDialog(this, "Please enter a valid number!");
}
    }//GEN-LAST:event_addStockConfirmActionPerformed

